criteria.query:
let online = Heartbeat | where TimeGenerated > ago(15m) | extend Host = toupper(tostring(split(Computer, '.')[0])) | distinct Host;
let sec = SecurityEvent | where TimeGenerated > ago(2h) | extend Host = toupper(tostring(split(Computer, '.')[0])) | summarize LastSecurity = max(TimeGenerated) by Host;
online | join kind=leftouter sec on Host
| where isnull(LastSecurity) or LastSecurity < ago(60m)
| extend LagMinutes = iff(isnull(LastSecurity), 120, datetime_diff('minute', now(), LastSecurity)), Problem = strcat(Host, ' is online but its Security audit is not reaching the workspace (newest Security event ', iff(isnull(LastSecurity), 'none in 2 hours', strcat(tostring(datetime_diff('minute', now(), LastSecurity)), ' minutes old')), ')')
| project Host, LastSecurity, LagMinutes, Problem
